+"""Derive strict client-to-proxy retry links for a read-only v2 audit.
+
+The original rows and journals are never modified.  A projection exists only
+when the reviewed normalizer proves one client/proxy bridge with a common
+identity, explicit parent/span link, and monotonic ordering.  It replaces the
+client namespace in the proxy retry ``retry_of`` field in a deep-copied row
+set, which is the namespace the frozen physical-request audit checks.
+"""
+from __future__ import annotations
+
+import copy
+import hashlib
+from pathlib import Path
+from typing import Any, Iterable
+
+NORMALIZER_SHA256 = "78b3c6b4b47263544f12f819a6d0896bb152a2b4f8ca493fcb678f357fc799af"
+_normalizer_path = Path(__file__).with_name("retry_bridge_normalize_v1.py")
+if hashlib.sha256(_normalizer_path.read_bytes()).hexdigest() != NORMALIZER_SHA256:
+    raise RuntimeError("reviewed retry-bridge normalizer hash differs")
+try:  # package import for scripts.validation.audit_v2_journals
+    from .retry_bridge_normalize_v1 import RetryBridgeError, normalize_retry_bridges
+except ImportError:  # pragma: no cover - direct script/import fallback
+    from retry_bridge_normalize_v1 import RetryBridgeError, normalize_retry_bridges
+
+
+class RetryAuditRepairError(ValueError):
+    """A row set cannot support a unique, in-memory retry projection."""
+
+
+def _is_exact_target(row: dict[str, Any], *, request_id: str, terminal: bool) -> bool:
+    return (
+        row.get("phase") == "model_request"
+        and row.get("event_kind") == ("model_request" if terminal else "model_request_start")
+        and row.get("terminal") is terminal
+        and row.get("request_id") == request_id
+    )
+
+
+def derive_retry_namespace_links(rows: Iterable[dict[str, Any]]) -> tuple[list[dict[str, Any]], list[dict[str, Any]], list[str]]:
+    """Return copied rows, proven bridges, and the exact changed event IDs.
+
+    This rejects a missing, ambiguous, already-projected, or unrelated target.
+    It intentionally changes only ``retry_of`` for the matching proxy start
+    and terminal rows.  All evidence values and the source row list stay
+    byte-for-byte represented as supplied by the caller.
+    """
+    source = list(rows)
+    try:
+        bridges = normalize_retry_bridges(source)
+    except RetryBridgeError as exc:
+        raise RetryAuditRepairError(str(exc)) from exc
+    derived = copy.deepcopy(source)
+    changed: list[str] = []
+    seen_proxy_retry_ids: set[str] = set()
+    for bridge in bridges:
+        proxy_retry = bridge.get("proxy_retry_request_id")
+        client_original = bridge.get("client_original_request_id")
+        proxy_original = bridge.get("proxy_original_request_id")
+        if not all(isinstance(value, str) and value for value in (proxy_retry, client_original, proxy_original)):
+            raise RetryAuditRepairError("normalizer returned an incomplete bridge identity")
+        if proxy_retry in seen_proxy_retry_ids:
+            raise RetryAuditRepairError("ambiguous duplicate proxy retry bridge")
+        seen_proxy_retry_ids.add(proxy_retry)
+        selected = [row for row in derived if _is_exact_target(row, request_id=proxy_retry, terminal=False) or _is_exact_target(row, request_id=proxy_retry, terminal=True)]
+        if len(selected) != 2 or sum(row.get("terminal") is False for row in selected) != 1 or sum(row.get("terminal") is True for row in selected) != 1:
+            raise RetryAuditRepairError(f"missing or ambiguous proxy projection rows for {proxy_retry!r}")
+        for row in selected:
+            if row.get("retry_of") != client_original:
+                raise RetryAuditRepairError(f"proxy retry namespace is not the proven client predecessor for {proxy_retry!r}")
+            event_id = row.get("event_id")
+            if not isinstance(event_id, str) or not event_id:
+                raise RetryAuditRepairError(f"proxy projection event has no identity for {proxy_retry!r}")
+            row["retry_of"] = proxy_original
+            changed.append(event_id)
+    if len(changed) != len(set(changed)):
+        raise RetryAuditRepairError("ambiguous duplicate projection event identities")
+    return derived, bridges, changed
