+"""Strict, isolated normalization for v2 client-to-proxy retry lineage.
+
+This wrapper never rewrites the original journal. A logical/retry slot is
+only a candidate: immutable event parent chains, identity fields, retry
+namespace, and monotonic ordering must also prove the bridge.
+"""
+
+from __future__ import annotations
+
+from collections import defaultdict
+from typing import Any, Iterable
+
+
+class RetryBridgeError(ValueError):
+    """The immutable events do not prove a unique retry bridge."""
+
+
+def _terminal(events: Iterable[dict[str, Any]], phase: str, event_kind: str):
+    return [
+        event
+        for event in events
+        if event.get("phase") == phase
+        and event.get("event_kind") == event_kind
+        and event.get("terminal") is True
+    ]
+
+
+def _slot_index(rows: list[dict[str, Any]], label: str):
+    out: dict[tuple[Any, Any], list[dict[str, Any]]] = defaultdict(list)
+    for row in rows:
+        key = (row.get("logical_request_id"), row.get("retry_index"))
+        if key[0] is None or key[1] is None:
+            raise RetryBridgeError(f"{label} has incomplete logical/retry identity")
+        out[key].append(row)
+    return out
+
+
+def _event_index(events: list[dict[str, Any]]):
+    out: dict[str, list[dict[str, Any]]] = defaultdict(list)
+    for row in events:
+        if row.get("event_id"):
+            out[row["event_id"]].append(row)
+    return out
+
+
+def _start_index(events: list[dict[str, Any]]):
+    out: dict[tuple[Any, ...], list[dict[str, Any]]] = defaultdict(list)
+    for row in events:
+        if not str(row.get("event_kind", "")).endswith("_start"):
+            continue
+        key = (
+            row.get("phase"),
+            row.get("event_kind"),
+            row.get("request_id"),
+            row.get("logical_request_id"),
+            row.get("retry_index"),
+        )
+        out[key].append(row)
+    return out
+
+
+def _one(index: dict[str, list[dict[str, Any]]], key: str, label: str):
+    rows = index.get(key, [])
+    if len(rows) != 1:
+        raise RetryBridgeError(f"missing or ambiguous {label} event {key!r}")
+    return rows[0]
+
+
+def _same_identity(rows: list[dict[str, Any]], label: str, include_retry_index: bool = True):
+    fields = ["case_id", "run_id", "attempt_id", "logical_request_id"]
+    if include_retry_index:
+        fields.append("retry_index")
+    for field in fields:
+        declared = {row.get(field) for row in rows if row.get(field) is not None}
+        if len(declared) > 1:
+            raise RetryBridgeError(f"{label} identity mismatch in {field}")
+
+
+def _check_chain(client_start, client_terminal, proxy_start, proxy_terminal, event_index, label):
+    rows = [client_start, client_terminal, proxy_start, proxy_terminal]
+    _same_identity(rows, label)
